/**
 * The `tag_artifact` built-in tool, enabled by
 * `defineArtifacts({ agentTool: true })` rather than
 * `AgentConfig.builtinTools`: its input schema and description are
 * generated from the declared kinds registry.
 */
import { z } from "zod/v3";
import * as z4 from "zod/v4";
import { defineTool } from "../../tools.js";
import { isJsonValue } from "../json-value.js";
import { isRecord } from "../is-record.js";
import { isZodV4Schema } from "../zod-schema.js";
export const TAG_ARTIFACT_TOOL_NAME = "tag_artifact";
const FREEFORM_DATA_DESCRIPTION = "Freeform JSON object payload for this kind.";
const TITLE_DESCRIPTION = "Short human-readable label shown in artifact lists.";
const KEY_DESCRIPTION = "Stable key, unique across kinds. Reusing it replaces that record instead of adding a new one.";
function isZod3Schema(schema) {
    return !isZodV4Schema(schema);
}
function tagArtifactInput(value) {
    if (!isRecord(value) || typeof value.kind !== "string" || !isJsonValue(value.data)) {
        throw new Error("tag_artifact: invalid input");
    }
    return {
        kind: value.kind,
        data: value.data,
        title: typeof value.title === "string" ? value.title : undefined,
        key: typeof value.key === "string" ? value.key : undefined,
    };
}
function kindVariant(name, schema) {
    return z.object({
        kind: z.literal(name),
        data: schema ?? z.object({}).passthrough().describe(FREEFORM_DATA_DESCRIPTION),
        title: z.string().optional().describe(TITLE_DESCRIPTION),
        key: z.string().trim().min(1).optional().describe(KEY_DESCRIPTION),
    });
}
function kindVariantV4(name, schema) {
    return z4.object({
        kind: z4.literal(name),
        data: schema ?? z4.looseObject({}).describe(FREEFORM_DATA_DESCRIPTION),
        title: z4.string().optional().describe(TITLE_DESCRIPTION),
        key: z4.string().trim().min(1).optional().describe(KEY_DESCRIPTION),
    });
}
/**
 * Kind schemas nest inside the tool's input schema, and a `zod/v4` schema
 * cannot nest inside a `zod/v3` one (or the reverse), so the wrapper uses
 * the kinds' own version.
 */
function tagArtifactInputSchema(kinds) {
    const declared = kinds.flatMap(([, schema]) => (schema === undefined ? [] : [schema]));
    const v4Count = declared.filter(isZodV4Schema).length;
    if (v4Count > 0 && v4Count < declared.length) {
        throw new Error("tag_artifact: artifact kind schemas mix zod/v3 and zod/v4; declare every kind schema with the same zod version");
    }
    if (v4Count === 0) {
        const [first, ...rest] = kinds.map(([name, schema]) => kindVariant(name, schema !== undefined && isZod3Schema(schema) ? schema : undefined));
        if (first === undefined) {
            throw new Error("tag_artifact requires at least one declared artifact kind");
        }
        return z.discriminatedUnion("kind", [first, ...rest]);
    }
    const [first, ...rest] = kinds.map(([name, schema]) => kindVariantV4(name, schema !== undefined && isZodV4Schema(schema) ? schema : undefined));
    if (first === undefined) {
        throw new Error("tag_artifact requires at least one declared artifact kind");
    }
    return z4.discriminatedUnion("kind", [first, ...rest]);
}
export function tagArtifactTool(config) {
    const kinds = Object.entries(config.kinds ?? {});
    if (kinds.length === 0) {
        // Discovery already errors on agentTool without kinds.
        throw new Error("tag_artifact requires at least one declared artifact kind");
    }
    const description = [
        "Tag a finished output as an artifact. Artifacts persist across sessions and are listed for the people supervising this agent.",
        "Kinds:",
        ...kinds.map(([name, kind]) => `- ${name}: ${kind.description}`),
    ].join("\n");
    const inputSchema = tagArtifactInputSchema(kinds.map(([name, kind]) => [name, kind.schema]));
    return defineTool({
        description,
        inputSchema,
        async execute(rawInput, ctx) {
            const input = tagArtifactInput(rawInput);
            const record = await ctx.artifacts.tag({
                kind: input.kind,
                data: input.data,
                title: input.title,
                key: input.key,
                source: "model",
            });
            return {
                tagged: true,
                id: record.id,
                kind: record.kind,
                key: record.key,
            };
        },
    });
}
